var n=`1072-chicken-adobo`;var a=`world-1072`;var t=`PH`;var s=`southeast-asia`;var r=4;var o=100;var d={en:`Chicken Adobo`,ua:`Курка адобо`};var h={en:`Chicken Adobo is a dish from Philippines prepared with chicken thigh, light soy sauce, white vinegar, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Курка адобо, страва кухні країни Філіппіни, яку готують із таких продуктів: куряче стегно, світлий соєвий соус, білий оцет, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`chicken-thigh`,900,`g`],[`light-soy-sauce`,95,`ml`],[`white-vinegar`,100,`ml`],[`garlic`,8,`clove`],[`bay-leaf`,3,`leaf`],[`black-peppercorn`,8,`pcs`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 43 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 43 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:43,i:[[`water`,300,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 9 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 9 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:9,i:[[`dark-brown-sugar`,18,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,35,`g`]]}];var c={slug:n,id:a,country:`PH`,region:s,servings:4,minutes:100,title:d,text:h,steps:g};export{t as country,c as default,a as id,o as minutes,s as region,r as servings,n as slug,g as steps,h as text,d as title};